-- ============================================================ -- Notify Tools -- Production Database Schema -- MySQL 8+ / Hostinger Shared Hosting -- Charset: utf8mb4 -- ============================================================ SET NAMES utf8mb4; SET time_zone = '+05:30'; -- ============================================================ -- 1. ADMINS -- ============================================================ CREATE TABLE IF NOT EXISTS `admins` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(120) NOT NULL, `email` VARCHAR(190) NOT NULL, `password_hash` VARCHAR(255) NOT NULL, `role` ENUM('super_admin','admin','editor') NOT NULL DEFAULT 'admin', `status` ENUM('active','inactive','suspended') NOT NULL DEFAULT 'active', `last_login` DATETIME NULL DEFAULT NULL, `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uq_admin_email` (`email`), KEY `idx_admin_role` (`role`), KEY `idx_admin_status` (`status`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- 2. CATEGORIES -- ============================================================ CREATE TABLE IF NOT EXISTS `categories` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(120) NOT NULL, `slug` VARCHAR(150) NOT NULL, `icon` VARCHAR(255) DEFAULT NULL, `description` TEXT DEFAULT NULL, `sort_order` INT UNSIGNED NOT NULL DEFAULT 0, `status` ENUM('active','inactive') NOT NULL DEFAULT 'active', `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uq_category_slug` (`slug`), KEY `idx_category_status` (`status`), KEY `idx_category_sort` (`sort_order`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- 3. TOOLS -- Calculator code must NOT be stored in this table. -- tool_type maps to trusted files inside /modules/ -- ============================================================ CREATE TABLE IF NOT EXISTS `tools` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `category_id` BIGINT UNSIGNED DEFAULT NULL, `name` VARCHAR(160) NOT NULL, `slug` VARCHAR(180) NOT NULL, `icon` VARCHAR(255) DEFAULT NULL, `short_description` VARCHAR(500) DEFAULT NULL, `full_description` LONGTEXT DEFAULT NULL, `tool_type` VARCHAR(120) NOT NULL, `featured` TINYINT(1) NOT NULL DEFAULT 0, `popular` TINYINT(1) NOT NULL DEFAULT 0, `status` ENUM('draft','published','inactive') NOT NULL DEFAULT 'draft', `seo_title` VARCHAR(255) DEFAULT NULL, `meta_description` VARCHAR(500) DEFAULT NULL, `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uq_tool_slug` (`slug`), KEY `idx_tool_category` (`category_id`), KEY `idx_tool_status` (`status`), KEY `idx_tool_featured` (`featured`), KEY `idx_tool_popular` (`popular`), KEY `idx_tool_type` (`tool_type`), KEY `idx_tool_updated` (`updated_at`), CONSTRAINT `fk_tool_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON UPDATE CASCADE ON DELETE SET NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- 4. PAGES -- ============================================================ CREATE TABLE IF NOT EXISTS `pages` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `title` VARCHAR(180) NOT NULL, `slug` VARCHAR(190) NOT NULL, `content` LONGTEXT DEFAULT NULL, `seo_title` VARCHAR(255) DEFAULT NULL, `meta_description` VARCHAR(500) DEFAULT NULL, `status` ENUM('draft','published','inactive') NOT NULL DEFAULT 'draft', `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uq_page_slug` (`slug`), KEY `idx_page_status` (`status`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- 5. SETTINGS -- ============================================================ CREATE TABLE IF NOT EXISTS `settings` ( `setting_key` VARCHAR(150) NOT NULL, `setting_value` LONGTEXT DEFAULT NULL, PRIMARY KEY (`setting_key`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- 6. ADS -- ============================================================ CREATE TABLE IF NOT EXISTS `ads` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `name` VARCHAR(150) NOT NULL, `placement` VARCHAR(100) NOT NULL, `ad_code` LONGTEXT DEFAULT NULL, `status` ENUM('active','inactive') NOT NULL DEFAULT 'inactive', PRIMARY KEY (`id`), UNIQUE KEY `uq_ad_placement` (`placement`), KEY `idx_ad_status` (`status`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- 7. ANNOUNCEMENTS -- ============================================================ CREATE TABLE IF NOT EXISTS `announcements` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `message` VARCHAR(500) NOT NULL, `link` VARCHAR(2048) DEFAULT NULL, `status` ENUM('active','inactive') NOT NULL DEFAULT 'inactive', `start_at` DATETIME DEFAULT NULL, `end_at` DATETIME DEFAULT NULL, PRIMARY KEY (`id`), KEY `idx_announcement_status` (`status`), KEY `idx_announcement_dates` (`status`,`start_at`,`end_at`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- 8. AUDIT LOGS -- ============================================================ CREATE TABLE IF NOT EXISTS `audit_logs` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `admin_id` BIGINT UNSIGNED DEFAULT NULL, `action` VARCHAR(150) NOT NULL, `entity_type` VARCHAR(100) DEFAULT NULL, `entity_id` BIGINT UNSIGNED DEFAULT NULL, `ip_address` VARCHAR(45) DEFAULT NULL, `user_agent` VARCHAR(500) DEFAULT NULL, `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_audit_admin` (`admin_id`), KEY `idx_audit_action` (`action`), KEY `idx_audit_entity` (`entity_type`,`entity_id`), KEY `idx_audit_created` (`created_at`), CONSTRAINT `fk_audit_admin` FOREIGN KEY (`admin_id`) REFERENCES `admins` (`id`) ON UPDATE CASCADE ON DELETE SET NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- 9. LOGIN ATTEMPTS -- Used for admin login rate limiting. -- ============================================================ CREATE TABLE IF NOT EXISTS `login_attempts` ( `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `email` VARCHAR(190) DEFAULT NULL, `ip_address` VARCHAR(45) NOT NULL, `successful` TINYINT(1) NOT NULL DEFAULT 0, `attempted_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_login_email` (`email`), KEY `idx_login_ip` (`ip_address`), KEY `idx_login_time` (`attempted_at`), KEY `idx_login_ip_time` (`ip_address`,`attempted_at`), KEY `idx_login_email_time` (`email`,`attempted_at`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci; -- ============================================================ -- SAMPLE CATEGORIES -- ============================================================ INSERT IGNORE INTO `categories` ( `name`, `slug`, `icon`, `description`, `sort_order`, `status` ) VALUES ( 'Student & Exam Tools', 'student-exam-tools', 'graduation-cap', 'Useful calculators and utilities for students and competitive exam aspirants.', 10, 'active' ), ( 'Government Job Tools', 'government-job-tools', 'briefcase', 'Useful tools for government job applicants including age, eligibility and qualification calculations.', 20, 'active' ), ( 'Salary & Employee Tools', 'salary-employee-tools', 'wallet', 'Salary, DA, HRA, NPS and employee-related calculators.', 30, 'active' ), ( 'Finance Tools', 'finance-tools', 'calculator', 'EMI, interest, GST, discount and other finance calculators.', 40, 'active' ), ( 'Text Tools', 'text-tools', 'file-text', 'Word counting, character counting and text formatting utilities.', 50, 'active' ), ( 'Date & Time Tools', 'date-time-tools', 'calendar', 'Age, countdown and date calculation utilities.', 60, 'active' ), ( 'PDF Tools', 'pdf-tools', 'file', 'Privacy-friendly PDF utilities.', 70, 'active' ), ( 'Image Tools', 'image-tools', 'image', 'Image resizing, compression and conversion tools.', 80, 'active' ), ( 'Security & Generator Tools', 'security-generator-tools', 'shield', 'Password generators and other privacy-focused utilities.', 90, 'active' ); -- ============================================================ -- DEFAULT PAGES -- ============================================================ INSERT IGNORE INTO `pages` ( `title`, `slug`, `content`, `seo_title`, `meta_description`, `status` ) VALUES ( 'About Us', 'about', '', 'About Notify Tools', 'Learn about Notify Tools and our free online utility platform.', 'published' ), ( 'Contact Us', 'contact', '', 'Contact Notify Tools', 'Contact the Notify Tools team.', 'published' ), ( 'Privacy Policy', 'privacy-policy', '', 'Privacy Policy - Notify Tools', 'Learn how Notify Tools handles privacy and user information.', 'published' ), ( 'Terms & Conditions', 'terms-and-conditions', '', 'Terms & Conditions - Notify Tools', 'Terms and conditions for using Notify Tools.', 'published' ), ( 'Disclaimer', 'disclaimer', '', 'Disclaimer - Notify Tools', 'Important information regarding calculations and content provided by Notify Tools.', 'published' ); -- ============================================================ -- DEFAULT SETTINGS -- ============================================================ INSERT IGNORE INTO `settings` (`setting_key`,`setting_value`) VALUES ('site_name','Notify Tools'), ('site_tagline','Free Online Tools for Everyday Tasks'), ( 'site_description', 'Fast, private and easy-to-use calculators and utilities for students, job aspirants, employees and everyday needs.' ), ('site_url',''), ('contact_email',''), ('logo_path',''), ('favicon_path',''), ('primary_color','#0B2C5F'), ('secondary_color','#1D4ED8'), ('background_color','#F7F9FC'), ('font_family','Poppins'), ( 'default_seo_title', 'Notify Tools - Free Online Calculators & Utility Tools' ), ( 'default_meta_description', 'Free online calculators and utilities for students, job aspirants, employees and everyday tasks.' ), ( 'homepage_seo_title', 'Notify Tools - Free Online Tools for Everyday Tasks' ), ( 'homepage_meta_description', 'Fast, private and easy-to-use calculators and utilities from Notify Tools.' ), ('whatsapp_url',''), ('telegram_url',''), ('youtube_url',''), ('facebook_url',''), ('instagram_url',''), ('pwa_app_name','Notify Tools'), ('pwa_short_name','Notify Tools'), ('pwa_theme_color','#0B2C5F'), ('pwa_background_color','#FFFFFF'), ('dark_mode_enabled','1'), ('pwa_enabled','1'), ('site_search_enabled','1'), ('ads_enabled','0'), ('analytics_code',''), ('maintenance_mode','0'), ('robots_indexing','1'), ('timezone','Asia/Kolkata'); -- ============================================================ -- DEFAULT AD PLACEMENTS -- No real ad code is stored. -- ============================================================ INSERT IGNORE INTO `ads` ( `name`, `placement`, `ad_code`, `status` ) VALUES ( 'Homepage Top', 'homepage_top', '', 'inactive' ), ( 'Homepage Middle', 'homepage_middle', '', 'inactive' ), ( 'Tool Page Top', 'tool_top', '', 'inactive' ), ( 'Tool Result Area', 'tool_result', '', 'inactive' ), ( 'Tool Page Bottom', 'tool_bottom', '', 'inactive' ), ( 'Sidebar', 'sidebar', '', 'inactive' ), ( 'Footer Advertisement', 'footer', '', 'inactive' ); -- ============================================================ -- INITIAL TOOL RECORDS -- Modules will be created later inside /modules/. -- These are initially drafts. -- ============================================================ INSERT IGNORE INTO `tools` ( `category_id`, `name`, `slug`, `icon`, `short_description`, `full_description`, `tool_type`, `featured`, `popular`, `status`, `seo_title`, `meta_description` ) SELECT `id`, 'Age Calculator', 'age-calculator', 'calendar', 'Calculate your exact age in years, months and days.', 'Calculate your exact age, next birthday and total age information.', 'age-calculator', 1, 1, 'draft', 'Age Calculator - Calculate Your Exact Age', 'Calculate your exact age in years, months and days using the free Notify Tools Age Calculator.' FROM `categories` WHERE `slug` = 'date-time-tools' LIMIT 1; INSERT IGNORE INTO `tools` ( `category_id`, `name`, `slug`, `icon`, `short_description`, `full_description`, `tool_type`, `featured`, `popular`, `status`, `seo_title`, `meta_description` ) SELECT `id`, 'Percentage Calculator', 'percentage-calculator', 'percent', 'Calculate percentages quickly and easily.', 'Calculate percentages, percentage differences and percentage changes.', 'percentage-calculator', 1, 1, 'draft', 'Percentage Calculator - Free Online Tool', 'Calculate percentages quickly using the free Notify Tools Percentage Calculator.' FROM `categories` WHERE `slug` = 'student-exam-tools' LIMIT 1; INSERT IGNORE INTO `tools` ( `category_id`, `name`, `slug`, `icon`, `short_description`, `full_description`, `tool_type`, `featured`, `popular`, `status`, `seo_title`, `meta_description` ) SELECT `id`, 'Negative Marking Calculator', 'negative-marking-calculator', 'check-circle', 'Calculate your exam score after negative marking.', 'Calculate final exam marks, attempted questions and accuracy after negative marking.', 'negative-marking-calculator', 1, 1, 'draft', 'Negative Marking Calculator for Competitive Exams', 'Calculate your final competitive exam score after negative marking.' FROM `categories` WHERE `slug` = 'student-exam-tools' LIMIT 1; INSERT IGNORE INTO `tools` ( `category_id`, `name`, `slug`, `icon`, `short_description`, `full_description`, `tool_type`, `featured`, `popular`, `status`, `seo_title`, `meta_description` ) SELECT `id`, 'EMI Calculator', 'emi-calculator', 'calculator', 'Calculate monthly EMI, total interest and total repayment.', 'Estimate monthly loan EMI, total interest and total payment.', 'emi-calculator', 1, 1, 'draft', 'EMI Calculator - Calculate Monthly Loan EMI', 'Calculate loan EMI, total interest and total payment with Notify Tools.' FROM `categories` WHERE `slug` = 'finance-tools' LIMIT 1; -- ============================================================ -- IMPORTANT SECURITY NOTES -- ============================================================ -- No administrator account is inserted here. -- -- The first administrator will be created later using: -- -- /admin/setup-admin.php -- -- Passwords must be stored with: -- -- password_hash($password, PASSWORD_DEFAULT) -- -- Login validation must use: -- -- password_verify($password, $storedHash) -- -- Never commit real database passwords or admin passwords -- to GitHub. -- -- Old login attempts may later be cleaned using: -- -- DELETE FROM login_attempts -- WHERE attempted_at < (NOW() - INTERVAL 30 DAY); -- -- ============================================================ -- END OF NOTIFY TOOLS DATABASE -- ============================================================
